  load(1,26);click("C");click("Z");click("A");click("Check my word");check(!(Boolean)field(state(),"won"),"Incorrect word won");click("Undo letter");click("Undo letter");click("Undo letter");click("C");click("A");click("T");click("Check my word");screen("letter-word");
